import heapq

def top_k(stream, k):
    """The k largest items, streamed; memory is O(k)."""
    if k <= 0:
        return []
    heap = []
    for item in stream:
        if len(heap) < k:
            heapq.heappush(heap, item)
        elif item > heap[0]:
            heapq.heapreplace(heap, item)
    return sorted(heap, reverse=True)
```

